eval(expr, assignment):
  if expr is VAR(i): return assignment[i]
  if expr is CONST(c): return c
  if expr is TMIN(e1, e2): return min(eval(e1), eval(e2))
  if expr is TPLUS(e1, e2): return eval(e1) + eval(e2)

